/* L1 — λ */
RULE(1,'Допиши формулу: количество теплоты, нужное для плавления тела массой m, взятого при температуре плавления, Q = …','λ · m',['c · m · Δt','λ / m','q · m'],
{short:'Q = λm. λ — сколько Дж на 1 кг.',
explain:'При температуре плавления температура не меняется, поэтому Δt тут нет, и cmΔt не подходит. Нужно λ (сколько Дж на 1 кг) умножить на массу: <b>Q = λm</b>. q·m — это сгорание топлива, совсем другой процесс.',
explain2:'λ<sub>льда</sub> = 340&nbsp;000 Дж/кг: на 1 кг — 340 кДж, на 2 кг — вдвое больше, на 0,5 кг — вдвое меньше. Значит, умножаем на массу.'});
G(1,()=>{const m=pick([0.2,0.3,0.5,0.8,1.5,2,2.5,3]);const Q=LAM*m;const it=pick(['кубиков льда в морозилке','льда для катка в ведре','снежков (снег — тот же лёд)','сосулек']);
return NUM(`Сколько энергии нужно, чтобы растопить ${N(m)} кг ${it}, уже нагретых до 0 °С? ${lamS('ice')}. Ответ дай в кДж.`,Q/1000,1,
{short:`Q = λm = 340&nbsp;000 · ${N(m)} = ${NN(Q)} Дж = ${N(Q/1000)} кДж.`,
explain:`Лёд уже при 0 °С, нагревать не надо — только плавить. Q = λ·m = 3,4·10⁵ · ${N(m)} = 340&nbsp;000 · ${N(m)} = ${NN(Q)} Дж = <b>${N(Q/1000)} кДж</b>.`,
explain2:`На каждый килограмм льда — 340 кДж. У нас ${N(m)} кг: 340 · ${N(m)} = ${N(Q/1000)} кДж.`});});
G(1,()=>{const k=pick(['pb','sn','al','cu']);const m=MET[k];const mass=pick([0.1,0.2,0.5,1,2]);const t0=pick([20,27,32]);const Q1=m.c*mass*(m.tm-t0),Q2=m.l*mass;
return NUM(`Какое количество теплоты нужно, чтобы расплавить ${N(mass)} кг ${m.g}, взятого при ${t0} °С? ${cS(m.g,m.c)}, ${lamS(k)}, t<sub>пл</sub> = ${m.tm} °С. Ответ дай в кДж.`,(Q1+Q2)/1000,1,
{hint:'Сначала нагрей до температуры плавления, потом плавь.',short:`Q = ${NN(rd(Q1,2))} + ${NN(Q2)} = ${NN(rd(Q1+Q2,2))} Дж ≈ ${N(rd((Q1+Q2)/1000,1))} кДж.`,
explain:`Два этапа:<br>1) Нагрев до ${m.tm} °С: Q₁ = c·m·Δt = ${NN(m.c)} · ${N(mass)} · (${m.tm} − ${t0}) = ${NN(rd(Q1,2))} Дж.<br>2) Плавление: Q₂ = λ·m = ${NN(m.l)} · ${N(mass)} = ${NN(Q2)} Дж.<br>Q = Q₁ + Q₂ = ${NN(rd(Q1+Q2,2))} Дж ≈ <b>${N(rd((Q1+Q2)/1000,1))} кДж</b>.<br>Только λm = ${N(Q2/1000)} кДж — ошибка: металл холодный, его сначала надо нагреть.`,
explain2:`Представь график: наклонная линия от ${t0} до ${m.tm} °С (нагрев, ${N(rd(Q1/1000,2))} кДж), потом полочка при ${m.tm} °С (плавление, ${N(Q2/1000)} кДж). Энергия на всём пути — сумма двух кусков.`});});
G(1,()=>{const k=pick(['ice','pb','sn','al','cu','fe']);const m=MET[k];const mass=pick([0.2,0.4,0.5,1.2,2,3]);const Q=m.l*mass;
return NUM(`При плавлении ${m.g}, взятого при температуре плавления, поглотилось ${N(Q/1000)} кДж. Какова масса ${m.g}? ${lamS(k)}. Ответ в кг.`,mass,2,
{short:`m = Q/λ = ${NN(Q)} / ${NN(m.l)} = ${N(mass)} кг.`,
explain:`Из Q = λm: m = Q / λ. Переводим: ${N(Q/1000)} кДж = ${NN(Q)} Дж. m = ${NN(Q)} : ${NN(m.l)} = <b>${N(mass)} кг</b>.`,
explain2:`На 1 кг ${m.g} нужно ${N(m.l/1000)} кДж. Сколько таких «килограммовых порций» в ${N(Q/1000)} кДж? ${N(Q/1000)} : ${N(m.l/1000)} = ${N(mass)}.`});});
G(1,()=>{const m=pick([1,2,3,5]);const Q=LAM*m;
return NUM(`Вода массой ${m} кг при 0 °С замёрзла (превратилась в лёд при 0 °С). Сколько энергии она <b>отдала</b>? ${lamS('ice')}. Ответ в кДж.`,Q/1000,0,
{short:`При кристаллизации выделяется λm = ${N(Q/1000)} кДж.`,
explain:`Кристаллизация — обратное плавлению. Выделяется ровно столько, сколько нужно на плавление: Q = λm = 340&nbsp;000 · ${m} = ${NN(Q)} Дж = <b>${N(Q/1000)} кДж</b>.`,
explain2:`Чтобы растопить ${m} кг льда, нужно ${N(Q/1000)} кДж. Когда эта вода снова замерзает, она «возвращает» те же ${N(Q/1000)} кДж — энергия не исчезает.`});});

